//! Byte-value generation, kept out of every timed region (a real caller
//! already holds the bytes it wants to write; only the DB round trip is
//! timed). Pattern mirrors `spikes/field-storage/src/gen.rs`'s
//! `ValueTemplate`, generalized to raw bytes (BLOB columns here, not TEXT).
use rand::distributions::Standard;
use rand::Rng;

/// A fixed-size random byte template, unique per (item, revision) via a
/// short marker spliced into its tail. Cloning + splicing is O(size) memcpy
/// instead of O(size) RNG draws, which matters once `size` reaches 64 KiB
/// and rows are generated by the tens of thousands.
pub struct ValueTemplate {
    base: Vec<u8>,
}

impl ValueTemplate {
    pub fn new(rng: &mut impl Rng, size: usize) -> Self {
        let base: Vec<u8> = (0..size).map(|_| rng.sample(Standard)).collect();
        Self { base }
    }

    /// `revision` distinguishes repeated writes to the same item — the
    /// update sweep reuses `value_for` every round, and each round must
    /// produce genuinely new bytes to exercise a real overwrite rather than
    /// a no-op content match.
    pub fn value_for(&self, item_no: i64, revision: u64) -> Vec<u8> {
        let marker = format!("{item_no:x}-{revision:x}");
        let marker = marker.as_bytes();
        let mut bytes = self.base.clone();
        let mlen = marker.len().min(bytes.len());
        let start = bytes.len() - mlen;
        bytes[start..].copy_from_slice(&marker[..mlen]);
        bytes
    }
}
